            C#

    // C# Program to check if a queue 
// of first n natural number can
// be sorted using a stack
using System;
using System.Linq;
using System.Collections.Generic;

class GFG
{
    // Function to check if given 
    // queue element can be sorted 
    // into another queue using a stack.
    static bool checkSorted(int n, 
                            ref Queue<int> q)
    {
        Stack<int> st = new Stack<int>();
        int expected = 1;
        int fnt;

        // while given Queue
        // is not empty.
        while (q.Count != 0) 
        {
            fnt = q.Peek();
            q.Dequeue();

            // if front element is 
            // the expected element
            if (fnt == expected)
                expected++;

            else 
            {
                // if stack is empty, 
                // push the element
                if (st.Count == 0) 
                {
                    st.Push(fnt);
                }

                // if top element is less than 
                // element which need to be 
                // pushed, then return false.
                else if (st.Count != 0 && 
                         st.Peek() < fnt) 
                {
                    return false;
                }

                // else push into the stack.
                else
                    st.Push(fnt);
            }

            // while expected element are
            // coming from stack, pop them out.
            while (st.Count != 0 && 
                   st.Peek() == expected) 
            {
                st.Pop();
                expected++;
            }
        }
        // if the final expected element 
        // value is equal to initial Queue
        // size and the stack is empty.
        if (expected - 1 == n && 
                st.Count == 0)
            return true;

        return false;
    }

    // Driver Code
    static void Main()
    {
        Queue<int> q = new Queue<int>();
        q.Enqueue(5);
        q.Enqueue(1);
        q.Enqueue(2);
        q.Enqueue(3);
        q.Enqueue(4);

        int n = q.Count;

        if (checkSorted(n, ref q))
            Console.Write("Yes");
        else
            Console.Write("No");
    }
}

