    // JavaScript Program to check if a queue
// of first n natural numbers can be sorted using a stack

let q = [];

// Function to check if given queue elements 
// can be sorted into another queue using a stack.
function checkSorted(n) {
    let st = [];
    let expected = 1;
    let fnt;

    // While given queue is not empty
    while (q.length !== 0) {
        fnt = q.shift(); // Remove front element

        // If front element is the expected element
        if (fnt === expected) {
            expected++;
        } else {
            // If stack is empty, push the element
            if (st.length === 0) {
                st.push(fnt);
            }
            // If top element is smaller than current element, return false
            else if (st[st.length - 1] < fnt) {
                return false;
            } else {
                st.push(fnt);
            }
        }

        // While expected elements are coming from stack, pop them out
        while (st.length !== 0 && st[st.length - 1] === expected) {
            st.pop();
            expected++;
        }
    }

    // If the final expected element value is equal to initial queue size
    // and the stack is empty, return true
    return (expected - 1) === n && st.length === 0;
}

